use bhoo::*;
use bhoo::android_calendar::{CalendarDate as D,CalendarState};
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_date_picker.rs"));}
fn d(y:i32,m:u8,day:u8)->D {D::new(y,m,day).unwrap()}
const B:Rect=Rect{x:0.,y:0.,width:350.,height:454.};
fn draw(ui:&mut Ui,s:&mut android_xml::LayoutState,input:Input)->Option<&'static str>{let mut a=None;ui.frame(input,B,0.,|f|a=fixture::LAYOUT.render(f,B,s));a}
fn click(ui:&mut Ui,s:&mut android_xml::LayoutState,label:&str,time:f64)->Option<&'static str>{let r=ui.semantics().iter().find(|n|n.label.as_ref()==label).unwrap_or_else(||panic!("missing {label}")).bounds;let p=[r.x+r.width/2.,r.y+r.height/2.];draw(ui,s,Input{pointer:Some(p),pressed:true,time,..Input::default()});draw(ui,s,Input{pointer:Some(p),released:true,time:time+0.01,..Input::default()})}
#[test] fn year_selection_preserves_month_and_clamps_leap_day(){let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.calendars.insert("date".into(),CalendarState::new(d(2020,1,1),d(2035,12,31),d(2024,2,29),1).unwrap());draw(&mut ui,&mut s,Input::default());click(&mut ui,&mut s,"Choose year",1.);draw(&mut ui,&mut s,Input{time:1.1,..Input::default()});assert_eq!(click(&mut ui,&mut s,"2023",1.2),Some("date"));assert_eq!(s.calendars["date"].selected(),d(2023,2,28));draw(&mut ui,&mut s,Input{time:1.3,..Input::default()});assert!(ui.semantics().iter().any(|n|n.label.as_ref()=="Next month"));}
#[test] fn picking_day_updates_date(){let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.calendars.insert("date".into(),CalendarState::new(d(2020,1,1),d(2035,12,31),d(2024,2,1),1).unwrap());draw(&mut ui,&mut s,Input::default());assert_eq!(click(&mut ui,&mut s,"15",1.),Some("date"));assert_eq!(s.calendars["date"].selected(),d(2024,2,15));}
#[test] fn year_and_day_views_crossfade_during_switch(){let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.calendars.insert("date".into(),CalendarState::new(d(2020,1,1),d(2035,12,31),d(2024,2,1),1).unwrap());draw(&mut ui,&mut s,Input::default());click(&mut ui,&mut s,"Choose year",1.);draw(&mut ui,&mut s,Input{time:1.02,..Input::default()});let commands=ui.frame(Input{time:1.145,..Input::default()},B,0.,|f|{fixture::LAYOUT.render(f,B,&mut s);});let alpha=|label:&str|commands.iter().find_map(|c|if let DrawCommand::Text{text,color,..}=c {if text.as_ref()==label {Some(color.3)}else{None}}else{None}).unwrap();let day=alpha("15");let year=alpha("2025");assert!((50..=78).contains(&day),"day opacity {day}");assert!((50..=78).contains(&year),"year opacity {year}");}
